SELECT o.*, p.name as patient_name, u.real_name as optometrist_name FROM optometry_record o LEFT JOIN patient p ON o.patient_id = p.id LEFT JOIN sys_user u ON o.optometrist_id = u.id
AND o.patient_id = #{patientId}
AND p.name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY o.check_date DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM optometry_record o LEFT JOIN patient p ON o.patient_id = p.id
AND o.patient_id = #{patientId}
AND p.name LIKE CONCAT('%', #{keyword}, '%')
